def get_weather(city):
    return {"Tokyo": "sunny, 22C", "Oslo": "snow, -3C"}.get(city, "unknown")

tools = {"get_weather": get_weather}

def fake_llm(question):
    # a real model would decide this; here the decision is canned
    city = question.split()[-1].strip("?")
    return {"tool": "get_weather", "args": {"city": city}}

question = "What is the weather in Tokyo?"
decision = fake_llm(question)
observation = tools[decision["tool"]](**decision["args"])
answer = f"Agent: it is {observation} in {decision['args']['city']}."
print(answer)
